<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { createResource } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { useListPersistence } from '../composables/useListPersistence'
import {
	statusPillClass,
	statusDotClass,
	resolveCabangFilter,
	STATUS_OPTIONS,
} from '../data/dataPengajuanStatus'

const router = useRouter()
const route = useRoute()

// Filter TERKUNCI dari query (mis. dari pemilih "Register: Sudah Pencairan" di
// FID/FPD chooser): status + marketing (field `marketing` = user_id/email).
// Selalu ikut di setiap fetch (list & count), tidak bisa dihapus dari panel filter.
const lockedStatus = computed(() => String(route.query.status || ''))
const lockedMarketing = computed(() => String(route.query.mu || ''))
const lockedMarketingName = computed(() => String(route.query.nm || ''))
const listPersistence = useListPersistence(
	() => `DataPengajuan:status=${lockedStatus.value}:marketing=${lockedMarketing.value}`,
)

// Tombol back: bila dibuka dari chooser "Register: Sudah Pencairan" (ada `m` =
// konteks marketing) → kembali ke halaman FID/FPD (5 menu) dengan konteksnya;
// selain itu (dibuka langsung dari Home/Bottom Nav) → kembali ke Home.
const backTarget = computed(() => {
	if (!route.query.m) return { name: 'Home' }
	const q = { m: route.query.m }
	if (route.query.nm) q.nm = route.query.nm
	if (route.query.mu) q.mu = route.query.mu
	return { name: 'FidFpdChooser', query: q }
})

function goToDetail(name) {
	router.push({ name: 'DataPengajuanDetail', params: { name } })
}

// Buka form Add Data Pengajuan.
function onCreate() {
	router.push({ name: 'DataPengajuanCreate' })
}

// ---- Pool field (in_list_view + standar) ----------------------------------
// Deskriptor kanonik STATIS: URUTAN kolom, label, tipe, & flag tampilan
// (avatar/pill). SENGAJA tidak fetch meta doctype: "Data Pengajuan" punya 163
// field & 25 link, jadi `getdoctype` memuat meta ~20 doctype tertaut → lambat &
// berat. Listview cuma butuh 9 label ini, yang sudah pasti di sini.
const DEFAULT_FIELDS = [
	{ key: 'marketing_full_name', label: 'Nama Marketing', fieldtype: 'Small Text', avatar: true },
	{ key: 'status', label: 'Status', fieldtype: 'Data', pill: true },
	{ key: 'nama_lengkap', label: 'Nama Lengkap', fieldtype: 'Data' },
	{ key: 'nopol', label: 'Nopol', fieldtype: 'Data' },
	{ key: 'pinjam', label: 'Pinjaman', fieldtype: 'Float' },
	{ key: 'cabang', label: 'Cabang', fieldtype: 'Link' },
	{ key: 'tanggal_pengajuan', label: 'Tanggal Pengajuan', fieldtype: 'Date' },
	{ key: 'tanggal_pencairan', label: 'Tanggal Pencairan', fieldtype: 'Date' },
	{ key: 'modified', label: 'Terakhir Diubah', fieldtype: 'Datetime' },
]
// Pool reaktif — sumber dropdown Filter/Sort/Columns & render tabel.
const availableFields = ref(DEFAULT_FIELDS.map((f) => ({ ...f })))

// Fetch = name + semua field pool (pool kecil) → toggle kolom cukup show/hide
// di klien tanpa perlu query ulang.
const ALL_FIELDS = computed(() => ['name', ...availableFields.value.map((f) => f.key)])

// Pilihan jumlah baris per halaman (pills, ala CRM).
const PAGE_SIZES = [20, 100, 500, 2500]

// ---- State ----------------------------------------------------------------
const openPanel = ref(null) // 'filter' | 'sort' | 'columns' | 'more' | null

// Daftar status untuk picker (sumber tunggal dari util status).
const STATUS_LIST = STATUS_OPTIONS

// Sort
const sortField = ref('modified')
const sortDir = ref('desc')

// Pilihan sort (ala Frappe: field standar + field penting Data Pengajuan).
const SORT_FIELDS = [
	{ key: 'modified', label: 'Terakhir Diubah' },
	{ key: 'creation', label: 'Dibuat' },
	{ key: 'name', label: 'ID' },
	{ key: 'tanggal_pengajuan', label: 'Tanggal Pengajuan' },
	{ key: 'tanggal_pencairan', label: 'Tanggal Pencairan' },
	{ key: 'nama_lengkap', label: 'Nama Lengkap' },
	{ key: 'marketing_full_name', label: 'Nama Marketing' },
	{ key: 'status', label: 'Status' },
	{ key: 'nopol', label: 'Nopol' },
	{ key: 'pinjam', label: 'Pinjaman' },
	{ key: 'cabang', label: 'Cabang' },
]

// Bottom-sheet Sort (gaya referensi): pilih di draft, baru diterapkan saat "Terapkan".
const showSortSheet = ref(false)
const sortFieldDraft = ref(sortField.value)
const sortDirDraft = ref(sortDir.value)
function openSort() {
	sortFieldDraft.value = sortField.value
	sortDirDraft.value = sortDir.value
	showSortSheet.value = true
}
function pickSortField(key) {
	sortFieldDraft.value = key
}
function toggleSortDirDraft() {
	sortDirDraft.value = sortDirDraft.value === 'asc' ? 'desc' : 'asc'
}
function applySort() {
	sortField.value = sortFieldDraft.value
	sortDir.value = sortDirDraft.value
	savePreferences()
	showSortSheet.value = false
	reload()
}

// Columns — default tampil 4 kolom utama; sisanya bisa di-add via panel Columns.
const visibleKeys = ref(['marketing_full_name', 'status', 'nama_lengkap', 'nopol'])
const shownColumns = computed(() =>
	availableFields.value.filter((c) => visibleKeys.value.includes(c.key)),
)

// Kolom untuk frappe-ui ListView (gaya FID/FPD): kolom pertama paling lebar.
// Flag avatar/pill/fieldtype ikut diteruskan → dipakai di slot #cell.
const listColumns = computed(() =>
	shownColumns.value.map((c, i) => ({ ...c, width: i === 0 ? 2 : 1.4 })),
)
const listOptions = {
	selectable: true,
	showTooltip: false,
	rowHeight: 52,
	onRowClick: (row) => goToDetail(row.name),
	selectionText: (n) => `${n} dipilih`,
	emptyState: { title: 'Tidak ada data', description: '' },
}
const listRef = ref(null)

// Seleksi
const selected = ref([])

// Data & pagination
const pageLength = ref(20)
const start = ref(0)
const rows = ref([])
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')
const totalCount = ref(0)

// ---- Filter (bottom-sheet) -------------------------------------------------
// Field teks (ID, Nama Nasabah, Nopol, Nama Marketing) pakai operator `like`;
// status pilih banyak → `in`; tanggal pengajuan rentang dari–sampai → `between`.
function blankFilter() {
	return {
		name: '',
		nama_lengkap: '',
		nopol: '',
		marketing_full_name: '',
		status: [],
		tanggal_dari: '',
		tanggal_sampai: '',
	}
}
const filterDraft = reactive(blankFilter()) // working copy saat sheet terbuka
const appliedFilter = reactive(blankFilter()) // yang sudah diterapkan ke query

// Jumlah field filter aktif (untuk badge angka di tombol filter header).
const activeFilterCount = computed(() => {
	const f = appliedFilter
	let n = 0
	if (f.name.trim()) n++
	if (f.nama_lengkap.trim()) n++
	if (f.nopol.trim()) n++
	if (f.marketing_full_name.trim()) n++
	if (f.status.length) n++
	if (f.tanggal_dari || f.tanggal_sampai) n++
	return n
})

// Batas cabang untuk user dibatasi (Pimcab) — null kalau tidak dibatasi.
// Di-resolve sekali saat onMounted, lalu selalu ikut di setiap fetch (list & count).
const cabangScope = ref(null)

// Filter AND yang dikirim ke get_list / get_count.
function buildFilters() {
	const arr = []
	const f = appliedFilter
	if (f.name.trim()) arr.push(['name', 'like', `%${f.name.trim()}%`])
	if (f.nama_lengkap.trim()) arr.push(['nama_lengkap', 'like', `%${f.nama_lengkap.trim()}%`])
	if (f.nopol.trim()) arr.push(['nopol', 'like', `%${f.nopol.trim()}%`])
	if (f.marketing_full_name.trim())
		arr.push(['marketing_full_name', 'like', `%${f.marketing_full_name.trim()}%`])
	if (f.status.length) arr.push(['status', 'in', [...f.status]])
	// Rentang tanggal pengajuan: between bila dua-duanya diisi, kalau tidak ≥/≤.
	if (f.tanggal_dari && f.tanggal_sampai)
		arr.push(['tanggal_pengajuan', 'between', [f.tanggal_dari, f.tanggal_sampai]])
	else if (f.tanggal_dari) arr.push(['tanggal_pengajuan', '>=', f.tanggal_dari])
	else if (f.tanggal_sampai) arr.push(['tanggal_pengajuan', '<=', f.tanggal_sampai])
	// Batasi ke cabang user (Pimcab). Selalu disertakan di list & count.
	if (cabangScope.value) arr.push(cabangScope.value)
	// Filter terkunci dari query (status + marketing terpilih dari chooser).
	if (lockedStatus.value) arr.push(['status', '=', lockedStatus.value])
	if (lockedMarketing.value) arr.push(['marketing', '=', lockedMarketing.value])
	return arr
}

// ---- Fetch ----------------------------------------------------------------
const list = createResource({
	url: 'frappe.client.get_list',
	makeParams() {
		// frappe.client.get_list lewat REST: fields/filters harus JSON string.
		const params = {
			doctype: 'Data Pengajuan',
			fields: JSON.stringify(ALL_FIELDS.value),
			order_by: `${sortField.value} ${sortDir.value}`,
			limit_start: start.value,
			limit_page_length: pageLength.value,
		}
		const andF = buildFilters()
		if (andF.length) params.filters = JSON.stringify(andF)
		return params
	},
	auto: false,
	onSuccess(data) {
		const batch = data || []
		// start 0 = query baru (replace); selain itu = Load more (append).
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === pageLength.value
		loading.value = false
	},
	onError(err) {
		error.value = err?.message || String(err)
		loading.value = false
	},
})

// Total baris yang cocok dengan filter (untuk counter "X of Y").
const countRes = createResource({
	url: 'frappe.client.get_count',
	makeParams() {
		const params = { doctype: 'Data Pengajuan' }
		const andF = buildFilters()
		if (andF.length) params.filters = JSON.stringify(andF)
		return params
	},
	auto: false,
	onSuccess(data) {
		totalCount.value = typeof data === 'number' ? data : Number(data) || 0
	},
})

// Reload dari awal (reset start + seleksi).
function reload() {
	start.value = 0
	clearSelection()
	error.value = ''
	loading.value = true
	list.fetch()
	countRes.fetch()
}

// Refresh list lalu tutup panel "more" (tombol Reload di dropdown).
function reloadAndClosePanel() {
	reload()
	openPanel.value = null
}

function loadMore() {
	start.value += pageLength.value
	loading.value = true
	list.fetch()
}

function setPageLength(n) {
	pageLength.value = n
	savePreferences()
	reload()
}

// ---- Import / Export ------------------------------------------------------
// Download file butuh navigasi form (bukan fetch) → submit form POST tersembunyi
// dgn csrf_token, persis cara desk Frappe memicu export.
function openUrlPost(url, params) {
	const form = document.createElement('form')
	form.method = 'POST'
	form.action = url
	form.style.display = 'none'
	const add = (k, v) => {
		const input = document.createElement('input')
		input.type = 'hidden'
		input.name = k
		input.value = v
		form.appendChild(input)
	}
	for (const [k, v] of Object.entries(params)) add(k, v)
	add('csrf_token', window.csrf_token || '')
	document.body.appendChild(form)
	form.submit()
	form.remove()
}

// Modal pilih format export (Excel / CSV).
const showExportModal = ref(false)
function openExport() {
	openPanel.value = null
	showExportModal.value = true
}

// Export tabel via endpoint bawaan Frappe (Excel/CSV) — ikut kolom & filter aktif.
function exportData(fileFormat) {
	const keys = ['name', ...shownColumns.value.map((c) => c.key)]
	const fields = keys.map((k) => `\`tabData Pengajuan\`.\`${k}\``)
	openUrlPost('/api/method/frappe.desk.reportview.export_query', {
		doctype: 'Data Pengajuan',
		file_format_type: fileFormat, // 'Excel' | 'CSV'
		fields: JSON.stringify(fields),
		filters: JSON.stringify(buildFilters().map((f) => ['Data Pengajuan', ...f])),
		order_by: `\`tabData Pengajuan\`.\`${sortField.value}\` ${sortDir.value}`,
		title: 'Data Pengajuan',
	})
	showExportModal.value = false
}

// ---- Filter (bottom-sheet, gaya referensi) --------------------------------
const showFilterSheet = ref(false)
const showStatusSheet = ref(false)

// Buka sheet → salin filter yang sudah diterapkan ke working copy (draft).
function openFilter() {
	Object.assign(filterDraft, { ...appliedFilter, status: [...appliedFilter.status] })
	showFilterSheet.value = true
}
// Tap satu status di sub-sheet → toggle di draft (pilih banyak).
function toggleStatusDraft(s) {
	const i = filterDraft.status.indexOf(s)
	if (i === -1) filterDraft.status.push(s)
	else filterDraft.status.splice(i, 1)
}
// Ringkasan status terpilih untuk ditampilkan di field.
const statusSummary = computed(() => {
	const n = filterDraft.status.length
	if (!n) return ''
	if (n === 1) return filterDraft.status[0]
	return `${filterDraft.status[0]} +${n - 1}`
})
// Terapkan draft → applied, lalu reload.
function applyFilter() {
	Object.assign(appliedFilter, { ...filterDraft, status: [...filterDraft.status] })
	saveFilter()
	showFilterSheet.value = false
	reload()
}
// Kosongkan semua filter.
function clearFilter() {
	Object.assign(filterDraft, blankFilter())
	Object.assign(appliedFilter, blankFilter())
	listPersistence.clearSession()
	showFilterSheet.value = false
	reload()
}

function saveFilter() {
	listPersistence.writeSession({ filters: appliedFilter })
}
function restoreFilter() {
	const saved = listPersistence.readSession({ filters: blankFilter() }).filters
	saved.status = saved.status.filter((value) => STATUS_LIST.includes(value))
	Object.assign(appliedFilter, saved)
	try {
		sessionStorage.removeItem(`dp-filter:${lockedStatus.value}|${lockedMarketing.value}`)
	} catch {}
}
function savePreferences() {
	listPersistence.writePreferences({
		sortField: sortField.value,
		sortDir: sortDir.value,
		visibleKeys: visibleKeys.value,
		pageLength: pageLength.value,
	})
}
function restorePreferences() {
	const saved = listPersistence.readPreferences({
		sortField: 'modified',
		sortDir: 'desc',
		visibleKeys: ['marketing_full_name', 'status', 'nama_lengkap', 'nopol'],
		pageLength: 20,
	})
	const allowedSort = new Set(SORT_FIELDS.map((field) => field.key))
	const allowedColumns = new Set(availableFields.value.map((field) => field.key))
	if (allowedSort.has(saved.sortField)) sortField.value = saved.sortField
	if (['asc', 'desc'].includes(saved.sortDir)) sortDir.value = saved.sortDir
	const columns = saved.visibleKeys.filter((key) => allowedColumns.has(key))
	visibleKeys.value = columns.length ? columns : ['marketing_full_name']
	if (PAGE_SIZES.includes(saved.pageLength)) pageLength.value = saved.pageLength
}

// ---- Kalender rentang Tanggal Pengajuan -----------------------------------
const showDateSheet = ref(false)
const calCursor = ref(new Date()) // bulan yang ditampilkan (tgl 1)
const rangeStart = ref('') // 'YYYY-MM-DD'
const rangeEnd = ref('')

const WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]

// Format lokal 'YYYY-MM-DD' (hindari pergeseran zona waktu dari toISOString).
function ymd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function parseYmd(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}

// Ringkasan rentang untuk field di sheet filter.
const dateSummary = computed(() => {
	const a = filterDraft.tanggal_dari
	const b = filterDraft.tanggal_sampai
	if (a && b) return `${formatDate(a)} – ${formatDate(b)}`
	if (a) return `Dari ${formatDate(a)}`
	if (b) return `Sampai ${formatDate(b)}`
	return ''
})

function openDateSheet() {
	rangeStart.value = filterDraft.tanggal_dari
	rangeEnd.value = filterDraft.tanggal_sampai
	const base = filterDraft.tanggal_dari || ymd(new Date())
	const d = parseYmd(base)
	calCursor.value = new Date(d.getFullYear(), d.getMonth(), 1)
	showDateSheet.value = true
}

const calLabel = computed(
	() => `${MONTHS[calCursor.value.getMonth()]} ${calCursor.value.getFullYear()}`,
)

// Sel kalender bulan aktif; null = padding awal pekan (mulai Senin).
const calDays = computed(() => {
	const year = calCursor.value.getFullYear()
	const month = calCursor.value.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7 // Senin = 0
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})

function prevMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() - 1, 1)
}
function nextMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() + 1, 1)
}

// Tap tanggal: tentukan mulai, lalu akhir (auto-tukar bila terbalik).
function pickDay(date) {
	const s = ymd(date)
	if (!rangeStart.value || (rangeStart.value && rangeEnd.value)) {
		rangeStart.value = s
		rangeEnd.value = ''
	} else if (s < rangeStart.value) {
		rangeEnd.value = rangeStart.value
		rangeStart.value = s
	} else {
		rangeEnd.value = s
	}
}

// Kelas tampilan tiap sel (endpoint / dalam rentang / hari ini / biasa).
function dayClass(date) {
	const s = ymd(date)
	const isStart = s === rangeStart.value
	const isEnd = s === rangeEnd.value
	if (isStart || isEnd) return 'rounded-full bg-primary font-semibold text-ui-onPrimary'
	if (rangeStart.value && rangeEnd.value && s > rangeStart.value && s < rangeEnd.value)
		return 'rounded-md bg-primary/10 text-primary'
	if (s === ymd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}

function clearDateRange() {
	rangeStart.value = ''
	rangeEnd.value = ''
}
// Simpan rentang ke draft (tetap di sheet filter setelah ini).
function applyDateRange() {
	filterDraft.tanggal_dari = rangeStart.value
	filterDraft.tanggal_sampai = rangeEnd.value
	showDateSheet.value = false
}

// ---- Sort -----------------------------------------------------------------
// Toggle arah sort (dipakai tombol kecil A→Z / Z→A di samping Sort).
function toggleSortDir() {
	sortDir.value = sortDir.value === 'asc' ? 'desc' : 'asc'
	savePreferences()
	reload()
}

// ---- Columns --------------------------------------------------------------
function toggleColumn(key) {
	const i = visibleKeys.value.indexOf(key)
	if (i === -1) {
		visibleKeys.value.push(key)
	} else if (visibleKeys.value.length > 1) {
		// Sisakan minimal 1 kolom.
		visibleKeys.value.splice(i, 1)
	}
	savePreferences()
}

// ---- Seleksi (dikelola frappe-ui ListView) --------------------------------
const selectedCount = computed(() => selected.value.length)
function onSelections(set) {
	selected.value = Array.from(set || [])
}
function clearSelection() {
	listRef.value?.toggleAllRows?.(false)
	selected.value = []
}

// ---- Util -----------------------------------------------------------------
function initials(nameStr) {
	if (!nameStr) return '?'
	return String(nameStr)
		.split(/\s+/)
		.filter(Boolean)
		.slice(0, 2)
		.map((w) => w[0]?.toUpperCase() || '')
		.join('')
}

// Tanggal "dd Mmm yyyy" (id-ID); kembalikan apa adanya kalau tak bisa di-parse.
function formatDate(v) {
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
}

// Jumlah pinjaman → "Rp 12.500.000" (id-ID). Kosong → "—".
function formatMoney(v) {
	if (v == null || v === '') return '—'
	const n = Number(v)
	if (Number.isNaN(n)) return String(v)
	return `Rp ${new Intl.NumberFormat('id-ID').format(n)}`
}

// Tampilan sel kolom biasa sesuai tipe field (Float diformat ribuan, Date/Datetime
// jadi tanggal singkat). Kosong → "—".
function cellDisplay(col, val) {
	if (val == null || val === '') return '—'
	if (['Float', 'Currency', 'Int'].includes(col.fieldtype)) {
		const n = Number(val)
		if (!Number.isNaN(n)) return new Intl.NumberFormat('id-ID').format(n)
	}
	if (['Date', 'Datetime'].includes(col.fieldtype)) return formatDate(val)
	return String(val)
}

// Warna titik status mengikuti util bersama (selaras workflow Flow Kredit).

onMounted(async () => {
	await refreshCsrfToken()
	// Resolusi batas cabang (Pimcab) SEBELUM fetch pertama, supaya tidak sempat
	// menampilkan data cabang lain lalu hilang.
	cabangScope.value = await resolveCabangFilter()
	restorePreferences()
	// Pulihkan filter terakhir (mis. setelah balik dari Detail) sebelum fetch pertama.
	restoreFilter()
	reload()
})
